CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin' AND banned_at IS NULL) $function$;
CREATE OR REPLACE FUNCTION public.has_perm(p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT EXISTS(SELECT 1 FROM public.profiles u WHERE u.id=auth.uid() AND u.banned_at IS NULL AND (u.role='admin' OR EXISTS(SELECT 1 FROM public.staff_members s WHERE s.user_id=u.id AND s.active AND p=ANY(s.perms)))) $function$;
CREATE OR REPLACE FUNCTION public.my_perms() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND banned_at IS NULL) THEN NULL WHEN public.is_admin() THEN ARRAY['orders','support','finance','stores','content'] ELSE (SELECT s.perms FROM public.staff_members s WHERE s.user_id=auth.uid() AND s.active AND cardinality(s.perms)>0) END $function$;
CREATE OR REPLACE FUNCTION finance_private.accountant() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $function$ SELECT EXISTS(SELECT 1 FROM public.staff_members s JOIN public.profiles u ON u.id=s.user_id WHERE s.user_id=auth.uid() AND u.banned_at IS NULL AND s.active AND 'finance'=ANY(s.perms)) $function$;